practical.solution:
fun isBalanced(text: String): Boolean {
    val pairs = mapOf(')' to '(', ']' to '[', '}' to '{')
    val open = mutableListOf<Char>()
    for (c in text) {
        when (c) {
            '(', '[', '{' -> open.add(c)
            ')', ']', '}' -> if (open.isEmpty() || open.removeAt(open.lastIndex) != pairs[c]) return false
        }
    }
    return open.isEmpty()
}

