practical.solution:
fun topWords(text: String, top: Int): List<Pair<String, Int>> {
    require(top >= 0) { "top must not be negative" }
    return Regex("[a-z]+").findAll(text)
        .groupingBy { it.value }
        .eachCount()
        .toList()
        .sortedWith(compareByDescending<Pair<String, Int>> { it.second }.thenBy { it.first })
        .take(top)
}

