// This cache should evict the least recently USED entry when it is full.
// Reading a key with get() counts as a use. It has bugs in both reading and eviction. Find and fix them.
class LruCache<K, V>(private val capacity: Int) {
    private val entries = LinkedHashMap<K, V>()

    fun get(key: K): V? = entries[key]

    fun put(key: K, value: V) {
        if (entries.size >= capacity) {
            entries.remove(entries.keys.last())
        }
        entries[key] = value
    }

    fun keys(): List<K> = entries.keys.toList()
}

practical.solution:
class LruCache<K, V>(private val capacity: Int) {
    init { require(capacity > 0) { "capacity must be positive" } }

    // accessOrder = true moves an entry to the end whenever it is read or written.
    private val entries = object : LinkedHashMap<K, V>(16, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<K, V>?): Boolean = size > capacity
    }

    fun get(key: K): V? = entries[key]

    fun put(key: K, value: V) { entries[key] = value }

    // Least recently used first.
    fun keys(): List<K> = entries.keys.toList()
}

