practical.solution:
fun <T> retry(
    times: Int,
    initialDelayMs: Long,
    maxDelayMs: Long,
    sleep: (Long) -> Unit,
    block: (attempt: Int) -> T
): T {
    require(times >= 1) { "times must be at least 1" }
    require(initialDelayMs >= 0 && maxDelayMs >= initialDelayMs) { "invalid delays" }
    var delay = initialDelayMs
    for (attempt in 1 until times) {
        try {
            return block(attempt)
        } catch (e: Exception) {
            sleep(delay)
            delay = minOf(delay * 2, maxDelayMs)
        }
    }
    return block(times) // The final failure propagates to the caller.
}

