    practicalCheck(1, "ok on 3 after [100, 200]") {
        val slept = mutableListOf<Long>()
        val value = retry(5, 100, 1_000, { slept += it }) { attempt -> if (attempt < 3) error("down") else "ok on $attempt" }
        "$value after $slept"
    }
    practicalCheck(2, "IllegalStateException after [100, 200, 250]") {
        val slept = mutableListOf<Long>()
        val failure = try { retry(4, 100, 250, { slept += it }) { error("down") }; "no failure" } catch (e: Exception) { e.javaClass.simpleName }
