practical.solution:
class TokenBucket(
    private val capacity: Int,
    private val refillPerSecond: Double,
    private val now: () -> Long
) {
    init { require(capacity > 0 && refillPerSecond > 0) { "capacity and refill rate must be positive" } }

    private var tokens = capacity.toDouble()
    private var updatedAt = now()

    @Synchronized
    fun tryAcquire(): Boolean {
        val time = now()
        // Ignore a clock that moves backwards rather than removing tokens.
        val elapsed = (time - updatedAt).coerceAtLeast(0)
        tokens = minOf(capacity.toDouble(), tokens + elapsed * refillPerSecond / 1000.0)
        updatedAt = maxOf(updatedAt, time)
        if (tokens < 1.0) return false
        tokens -= 1.0
        return true
    }
}

