fun practicalCheck(n: Int, expected: Any?, actual: () -> Any?) {
    val result = try { actual() } catch (e: Throwable) { "threw ${e.javaClass.simpleName}" }
    println(if (result == expected) "PASS $n" else "FAIL $n: expected $expected but was $result")
}

fun main() {
    practicalCheck(1, listOf(true, true, true, false)) {
        val bucket = TokenBucket(3, 1.0) { 0L }
        List(4) { bucket.tryAcquire() }
    }
    practicalCheck(2, listOf(true, false, false, true)) {
        var clock = 0L
        val bucket = TokenBucket(1, 2.0) { clock }
        val results = mutableListOf(bucket.tryAcquire(), bucket.tryAcquire())
        clock = 250; results += bucket.tryAcquire()
        clock = 500; results += bucket.tryAcquire()
        results
    }
    practicalCheck(3, 2) {
        var clock = 0L
        val bucket = TokenBucket(2, 1.0) { clock }
        bucket.tryAcquire(); bucket.tryAcquire()
        clock = 60_000 // A long idle period refills only up to capacity.
        List(5) { bucket.tryAcquire() }.count { it }
    }
    practicalCheck(4, false) {
        var clock = 10_000L
        val bucket = TokenBucket(1, 1.0) { clock }
        bucket.tryAcquire()
        clock = 5_000 // Clock moved backwards.
        bucket.tryAcquire()
    }
}
